func flatten(root *TreeNode) {
    cur := root
    for cur != nil {
        if cur.Left != nil {
            // 找左子树最右节点
            rightmost := cur.Left
            for rightmost.Right != nil {
                rightmost = rightmost.Right
            }
            rightmost.Right = cur.Right
            cur.Right = cur.Left
            cur.Left = nil
        }
        cur = cur.Right
    }
}

func flatten(root *TreeNode) {
    var prev *TreeNode
    var dfs func(*TreeNode)
    dfs = func(node *TreeNode) {
        if node == nil {
            return
        }
        // 逆前序：右 → 左 → 根
        dfs(node.Right)
        dfs(node.Left)
        node.Right = prev
        node.Left = nil
        prev = node
    }
    dfs(root)
}
